WITH payload AS (SELECT $archive_payload$[{"id":"137546ec-3dfe-55c0-9862-5981e417024d","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة -ضمان -الكفالة املعلقة على شرط -املطالبة بأتعاب احملاماة -طلب التعزير لرفع الدعوى -سبق الفصل يف الدعوى - صرف النظر عن طلب التعزير لعدم املصلحة .","document_number":"34280018","case_number":"3434238","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"كفالة -ضمان -الكفالة املعلقة على شرط -املطالبة بأتعاب احملاماة -طلب التعزير لرفع الدعوى -سبق الفصل يف الدعوى - صرف النظر عن طلب التعزير لعدم املصلحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34280018 :‬تاريخه‪1434/7/25 :‬هـ‬\n                    ‫رقم الدعوى‪3434238 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34346580‬تاريخه‪1434/11/2 :‬هـ‬\n\n\n‫كفالــة ‪ -‬ضمــان ‪ -‬الكفالــة املعلقــة علــى شــرط ‪ -‬املطالبــة بأتعــاب‬\n‫احملامــاة ‪ -‬طلــب التعزيــر لرفــع الدعــوى ‪ -‬ســبق الفصــل يف الدعــوى ‪-‬‬\n                  ‫صــرف النظــر عــن طلــب التعزيــر لعــدم املصلحــة ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا ذكــره بعــض فقهــاء احلنابلــة مــن انــه ال يصلــح تعليــق الضمــان‬\n            ‫علــى الشــرط أو وقــت ‪ ،‬انظــر الــكايف البــن قدامــة (‪. )134/2‬‬\n     ‫‪ -2‬الفقرة األولى من املادة الرابعة من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه وكالــة بــان موكلــه التــزم لــه بســداد‬\n‫مــا يف ذمــة املديــن للمدعــي ووعــد بإخــراج وحــدات ســكنية يف شــركة‬\n‫عقاريــة كضمــان حلقــة حتــى اســتالم املبلــغ ‪ ،‬لــم يفــرغ املدعــى عليــه‬\n‫الوحــدات املذكــورة ولــم يســدد املبلــغ عــن مكفولــه ‪ ،‬طلــب املدعــي‬\n‫إلــزام املدعــى عليــه أصالــة بدفــع املبلــغ الــذي التــزم بســداده عــن‬\n‫مكفولــة ‪ ،‬صــادق املدعــى عليــه وكالــة علــى صحــة الدعــوى ودفــع‬\n‫بــأن الكفالــة معلقــة علــى شــرط وهــو تنــازل املدعــى عــن املديــن لــدى‬\n‫احلقــوق املدنيــة مــن اجــل إخراجــه مــن الســجن ولــم يقــم املدعــي بإخــراج‬\n‫املديــن مــن الســجن ‪ ،‬طلــب املدعــى عليــه وكالــة رد دعــوى املدعــي‬\n\n                                                                                    ‫‪226‬‬\n\f      ‫وتعزيــزه لقــاء إقامــة هــذه الدعــوى ألن حقــه يف ذمــة املديــن ثابــت بقــرار‬\n      ‫مــن وزارة التجــارة وإلزامــه بدفــع أتعــاب احملامــاة ‪ ،‬صــادق املدعــي علــى‬\n      ‫الدفــع املذكــور وذكــر بــأن ســبب عــدم إخــراج الســجني هــو إجــازة‬\n      ‫العيــد ‪ ،‬ملــا ذكــره بعــض الفقهــاء مــن أن تعليــق الكفالــة علــى شــرط أو‬\n      ‫وقــت يبطلهــا ‪ ،‬وعلــى القــول بصحــة التعليــق فــإن الشــرط املعلــق عليــه‬\n      ‫لــم يتحقــق لــذا صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي جتــاه‬\n      ‫املدعــى عليــه ‪ ،‬صــرف النظــر عــن طلــب املدعــى عليــه تعزيــز املدعــي‬\n      ‫لعــدم املصلحــة يف ذلــك ‪ ،‬صــرف النظــر عــن مطالبــة املدعــى عليــه‬\n      ‫بأتعــاب احملامــاة وإفهامــه بــأن لــه التقــدم بهــا يف دعــوى مســتقله إذا‬\n      ‫اكتســب احلكــم القطعيــة ‪ ،‬اعتــرض املدعــي علــى احلكــم ‪ ،‬صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلة الشــيخ‬\n      ‫‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملة احملالة لنا‬\n      ‫مــن فضيلــة رئيــس احملكمة العامة بالرياض‪/‬املســاعد برقم ‪3434238‬‬\n      ‫وتاريــخ ‪ 1434/01/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34165191‬وتاريخ‬\n      ‫‪ 1434/01/19‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/06/18‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...‬وحضــر حلضــوره ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n      ‫بصفتــه وكيــا عــن ‪ ...‬الوكيــل الشــرعي عــن ‪ ...‬حامــل الســجل املدنــي‬\n      ‫رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب‬\n      ‫الريــاض برقــم ‪ 34712169‬يف ‪1434/6/5‬ه ـ والتــي تخــول الوكيــل‬\n\n‫‪227‬‬\n\f‫املطالبــة واملرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار‬\n‫واإلنــكار والصلــح والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع‬\n‫عنــه واإلجابــة واجلــرح والتعديــل والطعــن بالتزويــر‪ ،‬وقبــول األحــكام‬\n‫ونفيهــا واالعتــراض عليهــا وطلــب االســتئناف اهــ‪ ،‬وادعــى األول قائــا‬\n‫يف دعــواه ‪ :‬إن لــي يف ذمــة ‪ ...‬مبلغــا قــدره خمســمائة وخمســون ألــف‬\n‫ريــال‪ ،‬وقــد التــزم املدعــى عليــه ‪ ...‬مــوكل هــذا احلاضــر بســداد هــذا‬\n‫املبلــغ‪ ،‬وقــد وعدنــي املدعــى عليــه بــأن يفــرغ لــي وحــدات ســكنية يف‬\n‫شــركة ‪ ...‬الكويتيــة زعــم أنهــا لــه‪ ،‬كضمــان حتــى يســلم لــي املبلــغ‬\n‫الــذي أطالــب بــه وقــدره خمســمائة وخمســون ألــف ريــال‪ ،‬غيــر أنــه لــم‬\n‫يفــرغ لــي الوحــدات الســكنية‪ ،‬ولــم يســلم لــي املبلــغ الــذي أطالــب بــه‪،‬‬\n‫أطلــب إلــزام املدعــى عليــه أصالــة بــأن يســلم لــي مبلغــا قــدره خمســمائة‬\n‫وخمســون ألــف ريــال هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وكالــة قــال‪ :‬أطلــب مهلــة للجــواب ‪ ،‬ويف جلســة أخــرى حضــر الطرفــان‬\n‫احلاضــران يف اجللســة املاضيــة‪ ،‬وبســؤال املدعــى عليــه وكالــة عمــا‬\n‫اســتمهل مــن أجلــه‪ ،‬أبــرز مذكــرة مكونــة مــن ثــاث ورقــات ومرفــق‬\n‫واحــد‪ ،‬وباطالعــي عليهــا وجدتهــا تتضمــن أن املدعــى عليــه قــد التــزم‬\n‫بســداد مبلــغ وقــدره خمســمائة وخمســون ألــف ريــال للمدعــي ولكــن‬\n‫بشــرط وهــو إخــراج املدعــو‪ ... /‬مــن الســجن يف حينــه‪ ،‬غيــر أن‬\n‫املدعــي لــم يــوف بهــذا الشــرط ولــذا فــإن هــذا االلتــزام يعتبــر الغيــا‪،‬‬\n‫ثــم أن أصــل املــال املطالــب بــه ســبق الفصــل فيــه بالقــرار النهائــي رقــم‬\n‫‪ 33/225‬وتاريــخ ‪1433/11/23‬ه ـ الصــادر مــن مكتــب الفصــل يف‬\n‫منازعــات األوراق التجاريــة باملدينــة املنــورة ومــا زال املديــن ســجينا‬\n‫بســببه‪ ،‬فكيــف للمدعــي أن يطالــب بهــذا املبلــغ مــرة أخــرى‪ ،‬ممــا‬\n\n\n                                                                                     ‫‪228‬‬\n\f      ‫تقــدم يتبــن بــأن الدعــوى صوريــة كيديــة‪ ،‬ويظهــر منهــا كذلــك ان‬\n      ‫املدعــي قــد تعمــد اإلضــرار باملدعــى عليــه لتكليــف محامــي ملباشــرة‬\n      ‫هــذه القضيــة‪ ،‬وملــا ســبق فقــد طالــب املدعــى عليــه وكالــة مبــا يلــي‪:‬‬\n      ‫‪ /1 :‬صــرف النظــر عــن دعــوى املدعــي لعــدم أحقيتــه فيمــا يدعيــه‪/2 .‬‬\n      ‫تعزيــر املدعــي وذلــك لرفعــه دعــوى مبطالبــة ماليــة ســبق الفصــل فيهــا‬\n      ‫بحكــم قطعــي‪ /3 .‬حتمــل املدعــي ألتعــاب احملامــاة ا‪.‬ه ـ وبعــرض ذلــك‬\n      ‫علــى املدعــي أجــاب قائــا‪ :‬مــا ذكــره املدعــى عليــه يف مذكرتــه مــن أن‬\n      ‫موكلــه اشــترط علــي إخــراج املدعــو‪ ... /‬مــن الســجن مقابــل أن يلتــزم‬\n      ‫موكلــه بســداد املبلــغ املدعــى بــه فصحيــح‪ ،‬غيــر أن الوقــت كان وقــت‬\n      ‫إجــازة عيــد األضحــى ولــم أمتكــن مــن إخــراج املدعــو‪ ... /‬مــن الســجن‬\n      ‫بســبب أن احلقــوق املدنيــة والتــي تضبــط عندهــا التنــازالت قــد توقــف‬\n      ‫دوامهــا بســبب اإلجــازة‪ ،‬وبعــد اإلجــازة اتصلــت علــى املدعــى عليــه فقــال‬\n      ‫لــي‪ :‬ال تخرجــه مــن الســجن ألن هنــاك مــن يطالبــه غيــرك‪ ،‬أمــا مــا‬\n      ‫ذكــره املدعــى عليــه وكالــة مــن أنــه ســبق الفصــل يف املبلــغ املدعــى‬\n      ‫بــه مــن مكتــب الفصــل يف منازعــات األوراق التجاريــة بالقــرار رقــم‬\n      ‫‪ 33/225‬يف ‪1433/11/23‬ه ـ فصحيــح‪ ،‬غيــر أن التــزام املدعــى عليــه‬\n      ‫بالســداد كان بعــد القــرار هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه وكالــة قــال‪ :‬أطلــب اإلمهــال ملراجعــة موكلــي ‪ ،‬ويف جلســة أخــرى‬\n               ‫وفيهــا حضــر الطرفــان احلاضــران يف اجللســة املاضيــة‪ ،‬وبســؤال‬\n      ‫املدعــى عليــه وكالــة عمــا اســتمهل مــن أجلــه قــال‪ :‬مــا ذكــره املدعــي‬\n      ‫يف اجللســة املاضيــة مــن أنــه لــم يســتطع إخــراج املدعــو‪ .... /‬مــن الســجن‬\n      ‫بســبب أن احلقــوق املدنيــة والتــي تضبــط عندهــا التنــازالت قــد توقــف‬\n      ‫دوامهــا بســبب اإلجــازة‪ ،‬فــإن التنــازالت تضبــط حتــى يف اإلجــازة‪ ،‬ولــذا‬\n\n\n‫‪229‬‬\n\f‫فهــذا عــذر غيــر مقبــول‪ ،‬ثــم إن موكلــي شــرط علــى املدعــي أن يخــرج‬\n‫املدعــو‪ ... /‬مــن الســجن قبــل العيــد‪ ،‬غيــر أن املدعــي لــم يقــم بإخــراج‬\n‫املدعــو‪ ... /‬مــن الســجن قبــل العيــد‪ ،‬ولــذا يعتبــر الشــرط الغيــا كأن‬\n‫لــم يتــم‪ .‬وأمــا مــا ذكــره املدعــي مــن أن التــزام موكلــي كان بعــد قــرار‬\n‫مكتــب الفصــل فصحيــح هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي‬\n‫أجــاب قائــا‪ :‬مــا ذكــره املدعــى عليــه وكالــة غيــر صحيــح‪ ،‬فقــد أتاني‬\n‫املدعــى عليــه يف ‪1433/11/22‬ه ـ وقــال‪ :‬إنــي فاعــل خيــر‪ ،‬وأريــدك أن‬\n‫تعيننــي علــى فعــل اخليــر‪ ،‬وتعطينــي مبلــغ مائتــن وخمســن ألــف ألجــل‬\n‫أن نحــرر الشــقق التــي يف مكــة والفيــا التــي يف الريــاض مــن الرهــون‬\n‫وااللتزامــات التــي عليهــا ثــم نبيعهــا‪ ،‬ونســدد كل الذيــن يطالبــون ‪...‬‬\n‫مبــا فيهــم أنــت‪ ،‬وقلــت لــه ال مانــع لــدي‪ ،‬أنــا حقــي ثالثمائــة وســتني‬\n‫ألفــا صــدر بهــا قــرار وزارة التجــارة‪ ،‬وأنــا متنــازل عــن ثمانــن ألــف‪،‬‬\n‫فقــط أعطونــي حقــي‪ ،‬وكتبــت لــه شــيكا مســحوب ًا علــى مصــرف ‪...‬‬\n‫مببلــغ مائتــن وخمســن ألفــا‪ ،‬برقــم ‪ 157‬يف ‪1433/11/22‬ه ـ والتــزم‬\n‫لــي بإرجاعهــا بعــد بيــع الشــقق والفيــا ويف ‪1433/12/6‬ه ـ قــال لــي‪:‬‬\n‫إنــا حررنــا الشــقق والفيــا مــن الرهــون وااللتزامــات التــي عليهــا ونقلنــا‬\n‫الشــقق التــي يف مكــة باســمك‪ ،‬وســيتم إرســال مــا يثبــت ذلــك علــى‬\n‫بريــدك االلكترونــي‪ ،‬وأريــدك أن تكتــب التنــازل مــن غــدٍ ‪ ،‬فأنــا أريــد‬\n‫أن يخــرج ‪ ...‬بأســرع وقــت‪ .‬فقلــت‪ :‬لــك منــي أن أتنــازل عنــه غــدا وأكلــف‬\n‫وكيلــي يف املدينــة إلثبــات التنــازل‪ ،‬كمــا ســألته عــن املبلــغ املائتــن‬\n‫وخمســن ألــف‪ ،‬فقــال لــي‪ :‬إنــا ســنبيع الشــقق بعــد العيــد‪ ،‬وســوف‬\n‫نســددك بعدهــا‪ ،‬ويف اليــوم الثانــي كلمــت وكيلــي إلثبــات التنــازل‬\n‫لــدى احلقــوق‪ ،‬فقــال لــي‪ :‬إدارة احلقــوق مــا يســتقبلون اآلن ألنــه إجــازة‪،‬‬\n\n\n                                                                                     ‫‪230‬‬\n\f      ‫ثــم إن ‪ ...‬عليــه حكــم يف احلــق العــام شــهرين مــن ‪1434/11/23‬هــ‪،‬‬\n      ‫وبعــد العيــد اتصلــت عليــه فقــال‪ :‬إنــه لــم يتيســر بيعهــا‪ ،‬فطلبــت منــه‬\n      ‫إرجــاع املائتــن وخمســن ألــف التــي أخذهــا منــي‪ ،‬فأرجعهــا بحوالــة‬\n      ‫علــى حســابي يف ‪ ...‬بتاريــخ ‪1434/12/26‬ه ـ هكــذا أجــاب‪ .‬وبعرضــه‬\n      ‫علــى املدعــى عليــه وكالــة قــال‪ :‬ســأراجع موكلــي ‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر الطرفــان احلاضــران يف اجللســة املاضيــة واملدونــة هويتيهمــا‬\n      ‫ســلفا‪ ،‬وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل مــن أجلــه أبــرز‬\n      ‫مذكــرة مكونــة مــن صفحتــن علــى مطبوعــات مكتــب ‪ ...‬للمحامــاة‬\n      ‫وطلــب رصدهــا‪ ،‬وباطالعــي عليهــا وجــدت فيهــا مــا نصــه ( ومبراجعــة‬\n      ‫ـأت بجديــد أو‬  ‫مــا ذكــره املدعــي باجللســة املشــار إليهــا جنــد أنــه لــم يـ ِ‬\n      ‫اثبــات صحــة ادعائــه و ذلــك بالتفصيــل التالــي ‪ :‬أو ًال ‪ :‬تأكيــد املدعــي‬\n      ‫وإقــراره بربــط الســداد بشــرط اإلفــراج العاجــل وأنــه أقــر بــأن يتنــازل‬\n      ‫عنــه غــد ًا ويكلــف وكيلــه يف املدينــة بإثبــات التنــازل ‪ .‬ثانيـ ًا ‪ -:‬عندمــا‬\n      ‫بــدأ موكلــي بتنفيــذ عمليــة نقــل ملكيــة هــذه الصكــوك لصالــح‬\n      ‫املدعــي عــن طريــق بنــك ‪ ...‬وشــركة ‪ ...‬الكويتيــة تعطلــت عمليــة نقــل‬\n      ‫الصكــوك بعــض الوقــت ولــم يــف املدعــي يف وعــده بإخــراج املدعــو ‪... /‬‬\n      ‫ن مــن الســجن ‪ ،‬فأوقــف موكلــي عمليــة نقــل الصكــوك ورد لــه املبلــغ‬\n      ‫املدفــوع لــه يف بدايــة االتفــاق وهــو مائتــان وخمســون الــف ريــال بحوالــة‬\n      ‫علــي بنــك ‪ ...‬بتاريــخ ‪1434/12/26‬ه ـ ‪ .‬ثالث ـ ًا ‪ :‬صــدور حكمــن لــذات‬\n      ‫املبلــغ يف موضــوع واحــد فيــه اخــال بحجيــة األحــكام ‪ - :‬أصــل املبلــغ‬\n      ‫املطالــب بــه ســبق الفصــل فيــه بالقــرار النهائــي رقــم ‪ 33/225‬وتاريــخ‬\n      ‫‪1433/11/23‬ه ـ ‪ ،‬الصــادر مــن مكتــب الفصــل يف منازعــات األوراق‬\n      ‫التجاريــة باملدينــة املنــورة بالقضيــة رقــم ‪ ،33/1/179‬ومــا زال الســجني‬\n\n\n‫‪231‬‬\n\f‫‪ ، ... /‬ســجين ًا بســببه ‪ ،‬فــا يحــق للمدعــي أن يطالــب بهــذا املبلــغ مــرة‬\n‫أخــرى ‪ - .‬أقــر موكلــي بــأن الناشــئ بينــه وبــن املدعــي كان بعــد‬\n‫احلكــم بقــرار مكتــب الفصــل وهــذا صحيــح ‪ ،‬ولكــن املطالبــة املاليــة‬\n‫التــي ســبق الفصــل فيهــا بحكــم قطعــي ال يعنــي أن يصــدر حكــم آخــر‬\n‫لــذات املبلــغ يف موضــوع واحــد ‪ ،‬ألن املدعــي بهــذا أخــذ اكثــر مــن حقــه‬\n‫ـراء غيــر مشــروع وبــا ســبب هــذا باإلضافــة إلــى إخاللــه‬  ‫ومت إثــراءه إثـ ً‬\n‫بحجيــة األحــكام فــإذا صــدر لــه حكــم فإنــه يكــون حكمـ ًا ناســخ ًا‬\n‫أو ملغيـ ًا للحكــم الســابق وإمــا أن يكــون مؤكــد ًا لــه ويف احلالتــن يعــد‬\n‫مخالفــة للشــرع والنظــام ‪ .‬الطلبــات ‪ :‬لــذا فــإن موكلــي يصمــم علــى‬\n‫طلباتــه الســابقة ) ا‪.‬ه ـ ويف جلســة أخــرى حضــر الطرفــان احلاضــران‬\n‫يف اجللســة املاضيــة واملدونــة هوياتهمــا ســلفا‪ ،‬وقــرر املدعــي قائــا‪ :‬إن‬\n‫املدعــى عليــه أصالــة طلــب منــي التنــازل عــن مطالبــة املدعــو ‪ ...‬لدى اجلهة‬\n‫املختصــة قبــل عيــد األضحــى مقابــل أن يلتــزم بســداد املبلــغ املطالــب‬\n‫بــه‪ ،‬ولــم أمتكــن مــن التنــازل ملــا ذكرتــه مــن أن اجلهــة املختصــة بضبــط‬\n‫التنــازالت (إدارة احلقــوق املدنيــة) كانــت مغلقــة بســبب إجــازة عيــد‬\n‫األضحــى‪ ،‬وقــد اتصلــت علــى املدعــى عليــه بعــد اإلجــازة فطلــب منــي‬\n‫عــدم التنــازل هكــذا قــرر‪ .‬وبســؤال املدعــي هــل قــام بإخــراج املدعــو‬\n‫‪ ...‬مــن الســجن فأجــاب بقولــه‪ :‬ال لــم أخرجــه‪ ،‬ولــم أتنــازل لــدى اجلهــة‬\n‫املختصــة (إدارة احلقــوق املدنيــة) بنــاء علــى طلــب املدعــى عليه أصالة وال‬\n‫يــزال ‪ ...‬يف الســجن علــى ذمــة احلكــم الســابق هكــذا قــرر‪ .‬فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬ومبــا أن املدعــى عليــه وكالــة صــادق‬\n‫علــى أن موكلــه التــزم بســداد مبلــغ وقــدره خمســمائة وخمســون ألــف‬\n‫ريــال للمدعــي‪ ،‬ودفــع بــأن االلتــزام معلــق علــى شــرط وهــو إخــراج املدعو‬\n\n\n                                                                                     ‫‪232‬‬\n\f      ‫‪ ...‬مــن الســجن يف اليــوم التالــي لاللتــزام ولــم يكتــب املدعــي التنــازل‬\n      ‫مــن الغــد حســبما شــرط‪ ،‬وال يــزال احملكــوم عليــه ســجينا وصــادق‬\n      ‫علــى ذلــك املدعــي‪ ،‬ومبــا أن املدعــي صــادق علــى هــذا الدفــع وأنــه لــم‬\n      ‫يتنــازل ‪ ،‬وملــا قــرره بعــض فقهــاء احلنابلــة مــن أنــه ال يصــح تعليــق الضمــان‬\n      ‫علــى شــرط أو وقــت (ينظــر الــكايف للموفــق ابــن قدامــة ‪،)134/2‬‬\n      ‫وعلــى القــول بصحتــه فإنــه لــم يتــم حتقيــق الشــرط فــا يلــزم املشــروط‪،‬‬\n      ‫ومبــا أنــه ال مصلحــة قائمــة مشــروعة للمدعــى عليــه يف املطالبــة بتعزيــر‬\n      ‫املدعــي‪ ،‬وبنــاء علــى املــادة الرابعــة من نظام املرافعات الشــرعية والفقرة‬\n      ‫األولــى مــن الئحتهــا التنفيذيــة‪ ،‬ومبــا أن املطالبــة بأتعــاب احملامــاة ســابق‬\n      ‫ألوانــه لعــدم صــدور احلكــم واكتســابه القطعيــة‪ ،‬فقــد حكمــت‬\n      ‫بالتالــي‪ :‬أوال‪ :‬رد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه مــن هــذه‬\n      ‫الدعــوى‪ .‬ثانيــا‪ :‬صــرف النظــر عــن طلــب املدعــى عليــه تعزيــر املدعــي‪.‬‬\n      ‫ثالثــا‪ :‬صــرف النظــر عــن مطالبــة املدعــى عليــه بأتعــاب احملامــاة‪،‬‬\n      ‫وأفهمتــه بــأن لــه التقــدم بهــا يف دعــوى مســتقلة إذا اكتســب احلكــم‬\n      ‫القطعيــة‪ ،‬وبعرضــه علــى الطرفــن قــرر املدعــى عليــه وكالــة القناعــة‪،‬‬\n      ‫وقــرر املدعــي عــدم القناعــة وطلــب االســتئناف‪ ،‬فأجيــب لطلبــه‪ ،‬وأفهــم‬\n      ‫بــأن عليــه مراجعتنــا يــوم األربعــاء ‪1434/07/26‬ه ـ الســتالم نســخة مــن‬\n      ‫احلكــم لتقــدمي الئحتــه االعتراضيــة عليــه خــال مــدة ال تتجــاوز ثالثــن‬\n      ‫يومــا مــن التاريــخ املذكــور فــإن تأخــر عــن ذلــك ســقط حقــه يف طلــب‬\n      ‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/24‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/11/18‬ه ـ‬\n      ‫عــادت املعاملــة مــن محكمــة اإلســتئناف بالريــاض برقــم ‪342311580‬‬\n\n\n‫‪233‬‬\n\f‫وتاريــخ ‪1434/11/10‬ه ـ وبرفقهــا قــرار قضــاة الدائرة السادســة لتمييز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض رقــم ‪34346580‬‬\n‫وتاريــخ ‪1434/11/2‬ه ـ املتضمــن املصادقــة علــى احلكــم أ‪ .‬ه ـ وحتــى ال‬\n‫يخفــى جــرى حتريــره ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم‪ 34/165191‬وتاريــخ ‪1434/10/11‬ه ـ املرفــق بهــا الصــك الصادر‬\n‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪ ... /‬املســجل برقــم ‪...‬‬\n‫ا عــن ‪ ...‬يف‬‫وتاريــخ ‪1434/7/25‬ه ـ اخلــاص بدعــوى ‪ .../‬ضــد‪ ... /‬وكيـ ً‬\n‫مبلــغ مالــي علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم فضيلتــه‬\n‫أوال‪ :‬رد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‬\n            ‫ثانيــا‪ :‬صــرف النظــر عــن طلــب املدعــى عليــه تعزيــز املدعــي‬\n‫ثالثــا‪ :‬صــرف النظــر عــن مطالبــة املدعــى عليــه بأتعــاب احملامــاة وإفهامه‬\n‫بــأن لــه التقــدم بهــا يف دعــوى مســتقلة إذا اكتســب احلكــم القطعيــة‪،‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم ‪ .‬والل ــه املوفــق وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وآلــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪234‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":226,"source_page_end":234,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d47a88c3971e0995eeb8e39efcf28a4ded1b1c3f1ad6e7a707d11e607c893a8b","normalized_text_hash":"c5456cbfe8071f4325195ebc1f1742e7355e9308575c82885fc6973feee84d81","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p226-34280018"},{"id":"b1aea3e3-21ee-5cf9-ac5b-e20f5f1a4b40","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع سيارة على أقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -مصادقة املدعي على الدعوى -إلزام الكفيل بتسليم ما حل من الثمن وسداد املؤجل وقت حلوله -إفهام الكفيل بالرجوع على مكفوله مبا يدفعه .","document_number":"34221473","case_number":"3445394","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/25","year":"1434","subject":"كفالة غرم وأداء -بيع سيارة على أقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -مصادقة املدعي على الدعوى -إلزام الكفيل بتسليم ما حل من الثمن وسداد املؤجل وقت حلوله -إفهام الكفيل بالرجوع على مكفوله مبا يدفعه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34221473 :‬‬\n                          ‫َر ْق ُم الدعوى‪3445394 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34300116‬تاريخه ‪1434/8/17 :‬هـ‬\n\n\n      ‫كفالــة غــرم وأداء ‪ -‬بيــع ســيارة علــى أقســاط ‪ -‬ســداد جــزء مــن‬\n      ‫الثمــن والعجــز عــن ســداد الباقــي ‪ -‬مطالبــة الكفيــل بتســليم باقــي‬\n      ‫ثمــن ســيارة اشــتراها مكفولــه ‪ -‬مصادقــة املدعــي علــى الدعــوى‪ -‬إلــزام‬\n      ‫الكفيــل بتســليم مــا حــل مــن الثمــن وســداد املؤجــل وقــت حلولــه ‪ -‬إفهام‬\n                                 ‫الكفيــل بالرجــوع علــى مكفولــه مبــا يدفعــه ‪.‬‬\n\n\n\n\n                                     ‫‪ -‬قوله صلى اهلل عليه وسلم ‪« :‬الزعيم غارم» ‪.‬‬\n\n\n\n\n      ‫بــاع املدعــي ســيارة مقســطة علــى أقســاط شــهرية وقــد ســدد مــن هــذه‬\n      ‫القيمــة مبلغــا قــدره ثالثــون ألف ـ ًا وتبقــى مــن القيمــة مبلغــا قــدره ســتون‬\n      ‫ألف ـ ًا حــل منهــا مبلــغ قــدره ســتة وعشــرون ألف ـ ًا وقــد قــام املدعــى عليــه‬\n      ‫بكفالــة املشــتري كفالــة غــرم وأداء يف تلــك القيمــة لــذا طلــب إلزامــه‬\n      ‫بســداد املبلــغ احلــال وقــدره ســتة وعشــرون ألــف ريــال مــع االلتــزام بســداد‬\n      ‫باقــي األقســاط يف مواعيدهــا‪ ،‬صــادق املدعــى عليــه علــى مــا جــاء يف‬\n      ‫الدعــوى‪ ،‬بعــد اإلطــاع علــى العقــد املبــرم بــن الطرفــن‪ ،‬صــدر احلكم‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ احلــال للمدعــي مــع االلتــزام بســداد‬\n      ‫باقــي األقســاط يف مواعيدهــا‪ ،‬وأفهــم املدعــى عليــه أن لــه الرجــوع‬\n\n‫‪235‬‬\n\f‫علــى مكفولــه فيمــا يدفــع عنــه ‪ ،‬قــرر املدعــي القناعــة وقــرر املدعــى‬\n‫عليــه عــدم القناعــة ‪ ،‬متــت مصادقــة احلكــم مــن محكمــة االســتئناف‬\n                                                                    ‫بالريــاض ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪ 3445394‬وتاريــخ‬\n‫‪ 1434/01/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34223068‬وتاريــخ‬\n‫‪1434/01/26‬ه ـ ففــي يــوم الســبت املوافق‪1434/05/25‬ه ـ فتحــت‬\n‫اجللســة وفيهــا حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ............‬وادعــى علــى احلاضــر معــه ‪ ..........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .............‬قائــا يف حتريــر دعــواه عليــه لقــد بعــت‬\n‫علــى املــرأة ‪ .............../‬بتاريــخ ‪1432/1/20‬ه ـ ســيارة مــن نــوع داتســون‬\n‫نســيان غمارتــن أوراق جمــرك بقيمــة إجماليــة قدرهــا تســعون ألــف‬\n‫ريالــ‪ 90000‬مقســطة علــى أقســاط شــهرية بواقــع ألفــي ريالــ‪2000‬‬\n‫شــهريا اعتبــارا مــن ‪1432/2/25‬ه ـ وقــد ســددت مــن هــذه القيمــة مبلغــا‬\n‫قــدره ثالثــون ألــف ريالــ‪ 30000‬وتبقــى مــن القيمــة مبلغــا قــدره ســتون‬\n‫ألــف ريالــ‪ 60000‬حــل منــه حتــى تاريــخ هــذا اليــوم مبلغــا قــدره ســتة‬\n‫وعشــرون ألــف ريالــ‪ 26000‬وقــد قــام املدعــى عليــه احلاضــر بكفالــة‬\n‫املشــترية املذكــورة كفالــة غــرم وأداء يف تلــك القيمــة لــذا أطلــب‬\n‫إلزامــه بســداد املبلــغ احلــال وقــدره ســتة وعشــرون ألــف ريــال‪ 26000‬لــي‬\n\n                                                                                       ‫‪236‬‬\n\f      ‫مــع االلتــزام بســداد باقــي األقســاط يف مواعيدهــا هــذه دعــواي وأســأل‬\n      ‫املدعــى عليــه اجلــواب وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب‬\n      ‫قائــا إن مــا ذكــره املدعــي يف دعــواه كلــه صحيــح جملــة وتفصيــا‬\n      ‫فقــد كفلــت املــرأة املذكــورة يف قيمــة الســيارة التــي ذكــر ومــا ذكــره‬\n      ‫مــن املبلــغ املتبقــي والواصــل واحلــال كلــه صحيــح وأنــا مســتعد بالســداد‬\n      ‫ولكننــي أطلــب مهلــة لذلــك ‪ ،‬هــذا مــا لــدي وبعــرض ذلــك علــى املدعــي‬\n      ‫قــال ال أســتطيع إعطــاء املدعــى عليــه مهلــة وأطلــب إلزامــه مبــا ورد يف‬\n      ‫دعــواي هــذا مــا لــدي ثــم جــرى االطــاع علــى صــورة مــن العقــد الصــادر‬\n      ‫مــن معــرض ‪ ...........‬برقــم ‪ 2/5481‬وتاريــخ ‪1432/1/18‬ه ـ واملتضمــن‬\n      ‫بيــع املدعــي الســيارة املوصوفــة يف الدعــوى علــى املــرأة ‪ ........‬والقيمــة‬\n      ‫وكيفيــة الســداد كمــا ذكــر املدعــي وقيــام املدعــى عليــه بكفالــة‬\n      ‫املــرأة املذكــورة كفالــة غــرم وأداء وبعرضــه علــى املدعــى عليــه صــادق‬\n      ‫عليــه ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــال املدعــي‬\n      ‫ليــس لــدي مــا أضيفــه وقــال املدعــى عليــه أطلــب االحتفــاظ بحقــي يف‬\n      ‫الرجــوع علــى مكفولــي يف حالــة احلكــم علــي ‪ ،‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة واإلقــرار ولقولــه صلــى اهلل عليــه وســلم ‪»:‬الزعيــم‬\n      ‫غــارم» وبعــد اإلطــاع علــى العقــد املبــرم بــن الطرفــن ‪ ،‬لــكل مــا تقــدم‬\n      ‫فقــد حكمــت علــى املدعــى عليــه ‪ .............‬بدفــع املبلــغ احلــال للمدعــي‬\n      ‫وقــدره ســتة وعشــرون ألــف ريــال‪ 26000‬مــع االلتــزام بســداد باقــي‬\n      ‫األقســاط يف مواعيدهــا ‪ ،‬وأفهمــت املدعــى عليــه أن لــه الرجــوع علــى‬\n      ‫مكفولتــه فيمــا يدفــع عنهــا وبعــرض ذلــك علــى الطرفــن قــرر املدعــي‬\n      ‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة فجــرى إفهامــه بأنــه ســيجري‬\n      ‫تســليمه نســخة مــن احلكــم يف هــذا اليــوم لتقــدمي اعتراضــه عليــه يف‬\n\n\n‫‪237‬‬\n\f‫مــدة أقصاهــا ثالثــون يومــا مــن تاريخــه وكان ختــام اجللســة يف الســاعة‬\n‫‪ 11 : 30‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                     ‫‪1434/5/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/09/09‬ه ـ‬\n‫فتحــت اجللســة الســاعة ‪ 01 : 15‬وفيهــا كانــت قــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بالريــاض برقــم ‪ 341873030‬وتاريــخ‬\n‫‪1434/8/25‬ه ـ بشــرح فضيلــة رئيــس احملكمــة رقــم ‪341873030‬‬\n‫وتاريــخ ‪1434/9/8‬ه ـ وبرفقهــا القــرار الصــادر مــن الدائــرة السادســة‬\n‫لتمييــز القضايــا احلقوقيــة رقــم ‪ 34300116‬وتاريــخ ‪1434/8/17‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم وقــد ظهــر صــك احلكــم مبــا نصــه (‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك برقــم ‪34221473‬‬\n                                                          ‫وتاريــخ ‪1434/5/25‬ه ـ‬\n‫الصــادر مــن فضيلــة الشــيخ ‪ ......... /‬وأصدرنــا القــرار رقــم ‪34300116‬‬\n‫وتاريــخ ‪1434/8/17‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي‬\n‫اســتئناف ‪ ............‬توقيعــه وختمــه قاضــي اســتئناف ‪ .............‬توقيعــه‬\n‫وختمــه رئيــس الدائــرة ‪ ..............‬توقيعــه وختمــه ) أ‪.‬ه ـ لــذا جــرى إحلاقــه‬\n‫والتهميــش مبوجبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/09‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                        ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":235,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"91f336585060e39ddfef63cccd0d96f2be111e70f3c9eee4cfe87291b58e3f7f","normalized_text_hash":"a586e3fdd1950983044e173537e3721c718e1101d1bedcb9e0a63dfbed968261","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p235-34221473"},{"id":"dd5380f8-2f1f-54ca-a18e-5b6580dba507","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة -مطالبة الضامن للمضمون بأداء احلق لتخليصه من ضمانه كفالة يف قرض -ال تسمع دعوى اإلعسار إال بعد تكليف مدعيها بالسداد -لصاحب احلق اخليار يف الرجوع على الضامن أو املضمون -إلزام بالسداد .","document_number":"34203891","case_number":"33287027","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"كفالة -مطالبة الضامن للمضمون بأداء احلق لتخليصه من ضمانه كفالة يف قرض -ال تسمع دعوى اإلعسار إال بعد تكليف مدعيها بالسداد -لصاحب احلق اخليار يف الرجوع على الضامن أو املضمون -إلزام بالسداد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34203891 :‬تاريخه‪1434/5/1:‬هـ‬\n                        ‫رقم الدعوى‪33287027 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34240415:‬تاريخه ‪1434/6/13‬هـ‬\n\n\n      ‫كفالــة ‪ -‬مطالبــة الضامــن للمضمــون بــأداء احلــق لتخليصــه مــن‬\n      ‫ضمانــه كفالــة يف قــرض ‪ -‬ال تســمع دعــوى اإلعســار إال بعــد تكليــف‬\n      ‫مدعيهــا بالســداد ‪ -‬لصاحــب احلــق اخليــار يف الرجــوع علــى الضامــن‬\n                                                ‫أو املضمــون ‪ -‬إلــزام بالســداد ‪.‬‬\n\n\n\n\n      ‫قــال يف شــرح املنتهــى «وإذا طالــب ضامــن مضمونــا بتخليصــه مــن‬\n      ‫ضمانــه بــأداء احلــق لربــه لزمــه أي املديــن إن كفــل أو ضمــن بإذنــه‬\n      ‫أي املكفــول أو املضمــون وطولــب كفيــل أو ضامــن بذلــك ألنــه شــغل‬\n                          ‫ذمتــه مــن أجلــه بإذنــه فلزمــه تخليصهــا» ‪. 255/2‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بأنــه اقتــرض مبلغــا قــدرة‬\n      ‫مئتــان وواحــد وســتون الف ـ ًا وتســع مائــة وخمســة وســبعون ريــاال قرضــا‬\n      ‫حســنا وطلــب املدعــي اصالــة أن يعيــد املدعــى عليــه املبلــغ فرفــض وطلــب‬\n      ‫املدعــي إلــزام املدعــى عليــه بــان يســلم ملوكلــه املبلــغ الــذي اقترضــه منــه‬\n      ‫‪ ،‬أجــاب املدعــى عليــه بــان مــا ذكــره املدعــى غيــر صحيــح والصحيــح‬\n      ‫انــه أخــذ بضاعــة مــن إحــدى الشــركات علــى فتــرات باســم املدعــى‬\n      ‫اصالــة باتفــاق بــن الطرفــن واصبــح مجمــوع املبالــغ قدرهــا مئتــان‬\n\n‫‪239‬‬\n\f‫وواحــد وســتون الفــا وتســع مائــه وخمســه وســبعون ريــا ًال وانــه لــم يســدد‬\n‫منهــا شــيئ ًا للمدعــي وال للشــركة وانــه معســر ال يســتطيع الســداد وان‬\n‫الشــركة تطالــب املدعــى اصالــة باملبلــغ ‪ ،‬صــادق املدعــي وكالــة علــى‬\n‫جــواب املدعــى عليــه ســوى دعــوى اإلعســار فقــرر أنهــا غيــر صحيحــة‬\n‫‪ ،‬طالــب املدعــى وكالــة بإلــزام املدعــى عليــه بــأداء احلــق للشــركة‬\n‫حيــث أنهــا تطالبــه باملبلــغ ‪ ،‬قــرر ناظــر القضيــة أن هــذه املعاملــة بــن‬\n‫الطرفــن تعــد كفالــة مــن املدعــى للمدعــى عليــه جتــاه الشــركة‬\n‫وللضامــن مطالبــة املضمــون بتخليصــه مــن ضمانــه بــأداء احلــق لربــه‬\n‫كمــا قــرره ذلــك الفقهــاء ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بتســليم‬\n‫املبلــغ املدعــى بــه للش ــركة ال ــدائنة ‪ ،‬قــرر ناظــر القضيــة أن ذلــك ال مينــع‬\n‫مــن مطالبــة رب احلــق للضامــن وأيهمــا ســدد لــرب احلــق أوال كفــى ولــم‬\n                                                                  ‫يطالــب اآلخــر ‪.‬‬\n‫قــرر املدعــى القناعــة ‪ ،‬قــرر املدعــى عليــه عــدم القناعــة ‪ ،‬صــدق احلكم‬\n                                                      ‫من محكمة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة‪ .... /‬املســاعد برقــم ‪33287027‬‬\n‫وتاريــخ ‪ 1433/04/25‬ه ـ املقيــدة باحملكمــة برقــم ‪33777676‬‬\n‫وتاريــخ ‪ 1433/04/25‬ه ـ ففــي يــوم األربعــاء املوافــق‪1433/12/29 :‬هـ‬\n‫حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ .... :‬الوكيــل‬\n‫عــن‪ .... :‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال‬\n\n                                                                                         ‫‪240‬‬\n\f      ‫جــدة برقــم‪ 53629 :‬يف‪1431/6/15 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة‬\n      ‫واملدافعــة‪ ،‬وحضــر حلضــوره ‪ ....‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n      ‫رقــم‪ :‬وادعــى األول قائــا‪ :‬إن هــذا احلاضــر قــد اقتــرض مــن موكلــي‬\n      ‫مبلغــا قــدره‪ :‬مئتــان وواحــد وســتون ألــف وتســع مئــة وخمســة وســبعون‬\n      ‫ريــاال قرضــا حســنا‪ ،‬وقــد طلــب موكلــي منــه أن يرجــع مبلــغ القــرض‬\n      ‫فامتنــع‪ ،‬أطلــب إلــزام املدعــى عليــه بتســليم املبلــغ املدعــى بــه وقــدره‪:‬‬\n      ‫مئتــان وواحــد وســتون ألــف وتســع مئــة وخمســة وســبعون ريــال‪ ،‬هكــذا‬\n      ‫ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــره املدعي‬\n      ‫غيــر صحيــح‪ ،‬والصحيــح أننــي ســحبت بضاعــة مــن شــركة ‪ .........‬علــى‬\n      ‫فتــرات متفرقــة باســم املدعــي أصالــة باتفــاق بينــي وبينــه‪ ،‬وأصبــح‬\n      ‫مجمــوع مــا ســحبته مــن الشــركة املذكــورة مبلغــا قــدره‪ :‬مئتــان وواحــد‬\n      ‫وســتون ألــف وتســع مئــة وخمســة وســبعون ريــال‪ ،‬ولــم أســدد منهــا شــيئا‬\n      ‫للمدعــي أصالــة وال للشــركة‪ ،‬وأنــا اآلن شــخص معســر ال أســتطيع‬\n      ‫أن أســدده‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة أجــاب‬\n      ‫قائــا‪ :‬مــا ذكــره املدعــى عليــه صحيــح‪ ،‬هكــذا أجــاب‪ .‬ثم قــرر املدعي‬\n      ‫وكالــة قائــا‪ :‬أطلــب تأجيــل اجللســة حملاولــة الصلــح‪ ،‬هكــذا قــرر‪.‬‬\n      ‫ويف يــوم األربعــاء املوافــق‪1434/05/01 :‬ه ـ حضــر املدعــي وكالــة‪:‬‬\n      ‫واملدعــى عليــه أصالــة‪ :‬املثبــت حضورهمــا يف جلســة ســابقة‪ ،‬ثــم قــرر‬\n      ‫املدعــى عليــه قائــا‪ :‬إن شــركة ‪ .....‬تطالــب املدعــي باملبلــغ املدعــى بــه‬\n      ‫ألننــي أخذتهــا مــن الشــركة بإذنــه‪ ،‬وال تطالبنــي بشــيء‪ ،‬هكــذا قــرر‪.‬‬\n      ‫ثــم أضــاف املدعــي وكالــة قائــا‪ :‬مــا ذكــره املدعــى عليه آنفــا فصحيح‬\n      ‫عــدا إعســاره فغيــر صحيــح‪ ،‬وأطلــب إلزامــه بــأداء احلــق لربــه وتخليصــي‬\n      ‫مــن الديــن الــذي حلقنــي بســببه‪ ،‬هكــذا أضــاف‪ .‬فبنــاء علــى مــا ســلف‪،‬‬\n\n\n‫‪241‬‬\n\f‫وألن املدعــى عليــه قــرر أنــه أخــذ مــن شــركة ‪ ..........‬بضاعــة بقيمــة‬\n‫قدرهــا‪ :‬مئتــان وواحــد وســتون ألــف وتســع مئــة وخمســون ريــاال باســم‬\n‫املدعــي وبعــد إذنــه‪ ،‬وهــذه املعاملــة تعــد كفالــة مــن املدعــي للمدعــى‬\n‫وألن للضامــن مطالبــة املضمــون بتخليصــه مــن‬      ‫عليــه جتــاه الشــركة‪َّ ،‬‬\n‫رب احلـ ّـق كمــا قــرره الفقهــاء‪ ،‬قــال‬  ‫لربــه‪ ،‬ومطالبــة ّ‬\n                                                           ‫ضمانــه بــأداء احلـ ّـق ّ‬\n‫يف شــرح املنتهــى ‪( :255/2‬وإذا طالــب ضامـ ٌـن مضمون ـ ًا بتخليصــه مــن‬\n‫لربــه لزمــه أي‪ :‬املديــن إن كفــل أو ضمــن بإذنــه أي‪:‬‬    ‫ضمانــه بــأداء احلـ ّـق ِّ‬\n‫ذمته‬‫املكفــول أو املضمــون وطولــب كفيــل أو ضامــن بذلــك؛ ألنَّه شــغل َّ‬\n‫مــن أجلــه بإذنــه فلزمــه تخليصهــا)‪ ،‬وأمــا مــا دفــع بــه املدعــى عليــه بأنــه‬\n‫معســر ال يســتطيع الســداد فــا يلتفــت لهــذا الدفــع‪ ،‬ألن دعــوى اإلعســار‬\n‫ـررت إلــزام‬\n          ‫ال تســمع إال بعــد تكليــف مدعيــه بالســداد‪ ،‬لذلــك ك ِّلــه قـ ُ‬\n‫املدعــى بــه‬\n            ‫املدعــى عليــه‪ ........ :‬رخصــة إقامــة رقــم‪ :‬بتســليم املبلــغ َّ‬\n‫ـرب‬\n  ‫وقــدره‪ :‬مئتــان وواحــد وســتون ألــف وتســع مئــة وخمســون ريــاال لـ ّ‬\n‫رب احلـ ّـق للضامــن فأيهمــا‬  ‫احلــق‪ :‬شــركة ‪ ،.......‬وال مينــع هــذا مطالبــة ّ‬\n‫ـرب احلــق أو ًال كفــى ولــم يطالــب اآلخــر‪ ،‬وللمدعــي أو مــن ُينيبــه‬   ‫سـ َّـدد لـ ّ‬\n‫متابعــة تنفيــذ هــذا احلكــم علــى املدعــى عليــه بتســليم املبلــغ احملكــوم‬\n‫ـرب احلــق‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر املدعــي قناعتــه‬            ‫بــه لـ ّ‬\n‫باحلكــم‪ ،‬أمــا املدعــى عليــه فقــرر اعتراضــه بــدون الئحــة وأمــرت برفــع‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب‬\n‫التعليمــات‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/05/01 :‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم الســبت املوافــق‪1434/06/24 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار الدائــرة‬\n\n\n                                                                                            ‫‪242‬‬\n\f      ‫احلقوقيــة السادســة رقــم‪ 34240415 :‬يف‪1434/6/13 :‬ه ـ ونــص احلاجــة‬\n      ‫منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه وأمــرت بإحلاقــه علــى‬\n      ‫الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/06/24 :‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فق ــد ج ــرى‬\n      ‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبحافظــة‬\n      ‫جــدة‪ ،‬واملســجل بع ــدد ‪ 34203891‬وتاريــخ ‪1434/5/1‬ه ـ ‪،‬املتضمــن‬\n      ‫دعــوى ‪ ،‬احملكــوم في ــه مبــا دون باطنــه‪ ،‬وبدراس ــة احلكــم وص ــورة‬\n      ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى‬\n                                        ‫نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪243‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":239,"source_page_end":243,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"db81090d1ed823b4acefa5eda8257d16f9d6ed3b040a63e197bac4c4bb9c06ff","normalized_text_hash":"b3e3f9f8f48eed32ac9ef03d3d26bf9901377cea1bb8836821342a2b0d02e470","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p239-34203891"},{"id":"afa316d2-bbf0-5fcc-9ddb-92ffcf2f22fd","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة -بيع سيارة باآلجل -سداد الكفيل عن املدين -مطالبة الكفيل املدين مبا سدده عنه -قبول الدعوى على الغائب عن مجلس احلكم -اعتماد صكوك األحكام كبينة -تشرع اليمن يف جانب أقوى املتداعين -القضاء على الغائب -غياب املدعى عليه مع تبلغه مما يقوى جانب املدعي -تعذر تسليم صورة احلكم للغائب يقتضي رفع احلكم حملكمة الاستئناف .","document_number":"33430422","case_number":"32408198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/18","year":"1434","subject":"كفالة -بيع سيارة باآلجل -سداد الكفيل عن املدين -مطالبة الكفيل املدين مبا سدده عنه -قبول الدعوى على الغائب عن مجلس احلكم -اعتماد صكوك األحكام كبينة -تشرع اليمن يف جانب أقوى املتداعين -القضاء على الغائب -غياب املدعى عليه مع تبلغه مما يقوى جانب املدعي -تعذر تسليم صورة احلكم للغائب يقتضي رفع احلكم حملكمة الاستئناف .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33430422 :‬تاريخه‪1433/10/18 :‬هـ‬\n                    ‫رقم الدعوى‪32408198 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 349360‬تاريخه‪1434/1/12 :‬هـ‬\n\n\n ‫كفالــة ‪ -‬بيــع ســيارة باآلجــل ‪ -‬ســداد الكفيــل عــن املديــن ‪ -‬مطالبــة‬\n ‫الكفيــل املديــن مبــا ســدده عنــه ‪ -‬قبــول الدعــوى علــى الغائــب عــن‬\n ‫مجلــس احلكــم ‪ -‬اعتمــاد صكــوك األحــكام كبينــة ‪ -‬تشــرع اليمــن‬\n ‫يف جانــب أقــوى املتداعيــن ‪ -‬القضــاء علــى الغائــب ‪ -‬غيــاب املدعــى‬\n ‫عليــه مــع تبلغــه ممــا يقــوى جانــب املدعــي ‪ -‬تعــذر تســليم صــورة احلكــم‬\n                    ‫للغائــب يقتضــي رفــع احلكــم حملكمــة االســتئناف ‪.‬‬\n\n\n\n\n ‫‪ -1‬الالئحــة األولــى مــن املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية‬\n                                                       ‫والئحتــه التنفيذيــة‪.‬‬\n ‫‪ -2‬قــال بــن القيــم رحمــه اهلل يف إعــام املوقعــن (‪( : )101/1‬والــذي‬\n ‫جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعــن فــأي‬\n ‫اخلصمــن ترجــح جانبــه جعلــت اليمــن مــن جهتــه وهــذا مذهــب‬\n ‫اجلمهــور كأهــل املدينــة وفقهــاء احلديــث كاإلمــام أحمــد والشــافعي‬\n                                                           ‫ومالــك وغيرهــم)‪.‬‬\n ‫‪ -3‬مــا قــرره أهــل العلــم مــن القضــاء علــى الغائــب املســتتر وان لــم يكــن‬\n ‫مــع املدعــي بينــة حتــى ال يكــون االمتنــاع طريقــا إلــى إســقاط احلقــوق‬\n ‫التــي نصــب القاضــي حلفظهــا‪ .‬انظــر‪ :‬أدب القاضــي للمــاوردي‬\n                                                                      ‫(‪.)323/2‬‬\n\n\n                                                                                      ‫‪244‬‬\n\f      ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه كفلــه كفالــة غــرم وأداء يف‬\n      ‫ســيارة اشــتراها املدعــى عليــه مــن شــخص مببلــغ أربعــة وســبعني الــف‬\n      ‫ريــال ‪ ،‬ســدد منهــا املدعــى عليــه ثمانيــة وثالثــن ألــف ريــال واملتبقــي‬\n      ‫ســته وثالثــون ألــف ريــال ســددها املدعــي بعــد صــدور حكم عليــه بذلك‬\n      ‫‪ ،‬طلــب املدعــي إلــزام املدعــى عليــه بســداد هــذا املبلــغ ‪ ،‬ابــرز املدعــى‬\n      ‫صــك احلكــم الــذي عليــه ودون مضمونــه ‪ ،‬لترجــح جانــب املدعــي جــري‬\n      ‫حتليفــه علــى صحــة دعــواه وأن املدعــى عليــه لــم يســدد شــيئا مــن املبلــغ‬\n                                                                           ‫املدعــى بــه ‪.‬‬\n      ‫‪ ،‬ملــا ســبق ولئــا يكــون االمتنــاع عــن احلضــور ســببا إلســقاط احلقــوق‬\n      ‫صــدر احلكــم بإلــزام املدعــى عليــه الغائــب بدفــع املبلــغ املدعــى بــه‬\n      ‫للمدعــي ‪ ،‬نــص يف منطــوق احلكــم أن املدعــى عليــه الغائــب علــى حجتــه‬\n                        ‫متــى حضــر ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بينبــع ‪ ....‬املســاعد برقــم ‪ 32408198‬وتاريــخ ‪ 1432/09/14‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 321185775‬وتاريــخ ‪ 1432/09/14‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1433/10/17‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n      ‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى‬\n      ‫ا يف دعــواه إن املدعى‬   ‫علــى الغائــب عــن مجلــس احلكــم الشــرعي ‪ ...‬قائـ ً‬\n\n‫‪245‬‬\n\f‫عليــه الغائــب عــن املجلــس الشــرعي قــام بشــراء ســيارة نــوع ‪ ......‬غمــارة‬\n‫موديــل ‪2006‬م مــن ‪ ...‬مببلــغ وقــدره(‪ )74,000‬أربعــة وســبعون ألــف ريــال‬\n‫ســدد منهــا مبلغـ ًا وقــدره(‪ )38,000‬ثمانيــة وثالثــون ألــف ريــال ولم يســدد‬\n‫املبلــغ املتبقــي وقــدره(‪ )36,000‬ســتة وثالثــون ألــف ريــال وقــد قــام البائــع‬\n‫بتقــدمي دعــوى ضــدي لــدى فضيلتكــم لكونــي كفيــل غــارم وقــد صدر‬\n‫ضــدي صــك احلكــم رقم‪ 5/21‬وتاريــخ ‪1432/04/07‬ه ـ والذي يلزمني‬\n‫بدفــع املبلــغ احلــال بذمــة املدعــى عليــه وقدره(‪)36,000‬ســتة وثالثون ألف‬\n‫ريــال وقــد قمــت بســداد املبلــغ احلــال بذمــة املدعــى عليه وقــدره(‪)36,000‬‬\n‫ســتة وثالثــون ألــف ريــال وقــد همــش علــى صــك احلكــم بذلــك أطلــب‬\n‫ســؤال املدعــى عليــه واحلكــم بإلزامــه بدفــع املبلــغ الــذي ســددته عنــه‬\n‫وقــدره(‪ )36,000‬ســتة وثالثــون ألــف ريــال هــذه دعــواي وقــد ســبق أن‬\n‫تبلــغ املدعــى عليــه مبوعــد اجللســة يــوم الســبت املوافــق ‪1432/07/16‬ه ـ‬\n‫الســاعة التاســعة حســب منــوذج التبليــغ املرفــق باملعاملــة ولــم يحضــر وملــا‬\n‫ســبق واســتناد ًا علــى الفقــرة (‪ )1‬مــن املــادة اخلامســة واخلمســن مــن نظــام‬\n‫املرافعــات الشــرعية والئحتهــا التنفيذيــة ونصهــا ( إذا تبلــغ املدعــى عليــه‬\n‫لشــخصه أو وكيلــه الشــرعي يف القضيــة نفســها مبوعــد اجللســة أو‬\n‫أودع هــو أو وكيلــه مذكــرة بدفاعــه للمحكمــة قبــل اجللســة فيعــد‬\n‫احلكــم يف حقــه حضوري ـ ًا ســواء أكان غيابــه قبــل قفــل بــاب املرافعــة‬\n‫أم بعــده ) أ‪.‬ه ـ فلــذا قــررت الســير يف القضيــة وطلبــت مــن املدعــي‬\n‫وكالــه البينــة التــي تشــهد بصحــة دعــواه فأبــرز صــك احلكــم الصــادر‬\n‫مــن احملكمــة العامــة بينبــع برقــم ‪ 5/21‬وتاريــخ ‪1433/04/07‬ه ـ ثــم‬\n‫جــرى منــي ســؤال املدعــي وكالــه هــل لديــه زيــادة بينــه علــى مــا ذكــره‬\n‫فأجــاب بقولــه ليــس لــدي ســوى مــا ذكرتــه ومبــا أن املدعــى عليــه قــد‬\n\n\n                                                                                       ‫‪246‬‬\n\f      ‫تغيــب عــن اجللســة مــع تبلغــه باحلضــور إضافــة إلــى البينــة التــي قدمهــا‬\n      ‫املدعــي يرجــح قــوة جانــب املدعــي لــذا أفهمتــه بــأن اليمــن تتوجــه عليــه‬\n      ‫يف عــدم ســداد املدعــى عليــه للمبلــغ املدعــى بــه أو بعضــه فاســتعد‬\n      ‫باحللــف فجــرى منــي تخويفــه مبغبــة اليمــن الكاذبــة ففهــم ذلــك وحلــف‬\n      ‫ا ‪ ( :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي ســددت عــن املدعــى‬         ‫قائ ـ ً‬\n      ‫عليــه الغائــب عــن مجلــس احلكــم مبلغ ـ ًا وقدره(‪)36,000‬ســتة وثالثــون‬\n      ‫ألــف ريــال ولــم يســلمني منهــا أي مبلــغ أقســم بــاهلل علــى ذلــك) هكــذا‬\n      ‫حلــف فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي ومبــا أن املدعــى عليــه‬\n      ‫قــد تبلــغ لشــخصه نظامــا مبوعــد اجللســة ولــم يحضــر ونظــر ًا ملــا ورد‬\n      ‫يف الالئحــة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية والئحتهــا التنفيذيــة املشــار إليهــا بعاليــه ومبــا أن بينــة املدعــي‬\n      ‫بينــة غيــر موصلــه إال أن غيــاب املدعــى عليــه عــن املجلــس الشــرعي مــع‬\n      ‫تبلغــه لشــخصه يرجــح قــوة جانبــه واليمــن تتوجــه علــى أقــوى املتداعــن‬\n      ‫ولهــذا قــال ابــن القيــم رحمــه اهلل يف إعــام املوقعــن ‪ 101/1‬مــا نصــه‬\n      ‫(والــذي جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعيــن‬\n      ‫فــأي اخلصمــن ترجــح جانبــه جعلــت اليمــن مــن جهتــه وهــذا مذهــب‬\n      ‫اجلمهــور كأهــل املدينــة وفقهــاء احلديــث كاإلمــام أحمــد والشــافعي‬\n      ‫ومالــك وغيرهــم) ونظــر ًا ملــا قــرره جمــع مــن أهــل العلــم مــن القضــاء علــى‬\n      ‫الغائــب املســتتر وإن لــم يكــن مــع املدعــى بينــة حتــى ال يكــون االمتنــاع‬\n      ‫طريق ـ ًا إلــى إســقاط احلقــوق التــي نصــب القاضــي حلفظهــا انظــر أدب‬\n      ‫القاضــي للمــاوردي ( ‪ )323/2‬ومبــا أن املدعــي حلــف اليمــن املطلوبــة‬\n                                                          ‫منــه كمــا هــو مفصــل أعــاه‬\n      ‫ـدي صحــة دعــوى املدعــي وحكمــت علــى املدعــى عليــه‬           ‫لــذا فقــد ثبــت لـ َّ‬\n\n‫‪247‬‬\n\f‫حكمـ ًا حضوريـ ًا بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره(‪36,000‬‬\n‫)ســتة وثالثــون ريــال والغائــب علــى حجتــه متــى حضــر ‪ ،‬وبعــرض احلكم‬\n‫علــى املدعــي قنــع بــه وقــررت إكمــال مــا يلــزم حيــال إبــاغ املدعــى عليــه‬\n‫الغائــب باحلكــم حســب التعليمــات ‪ ،‬ثــم رفــع كامــل املعاملــة حــال‬\n‫االقتضــاء إلــى محكمــة االســتئناف لدراســة احلكــم وتدقيقــه حســب‬\n‫املتبــع ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n            ‫وســلم حــرر يف ‪1433/10/17‬ه ـ الســاعة العاشــرة والنصــف ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا يــوم األحــد املوافــق ‪1433/12/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة وخمســة وأربعــون دقيقــة وقــد ســبق‬\n‫الكتابــة لرئيــس محضــري اخلصــوم باحملكمــة باخلطــاب ذي الرقــم‬\n‫‪ 331878864‬وتاريــخ ‪1433/10/23‬ه ـ لتســليم املدعــى عليــه ‪ ...‬صــورة‬\n‫مــن صــك احلكــم رقــم ‪ 33430422‬وتاريــخ ‪1433/10/18‬ه ـ إلبــداء‬\n‫مــدى قناعتــه باحلكــم مــن عدمهــا وقــد وردنــا خطابهــم ذي الرقــم‬\n‫‪ 331878864‬وتاريــخ ‪1433/11/03‬ه ـ املتضمن(إشــارة إلــى خطابكم‬\n‫رقــم ‪ 331878864‬وتاريخ‪1433/10/23‬ه ـ بشــأن تســليم املدعــو‬\n‫‪ ...‬صــورة مــن صــك احلكــم الغيابــي احملكــوم بــه لصالــح ‪ ...‬عليــه‬\n‫نفيدكــم بأنــه مت التوجــه إلــى منــزل املدعــى عليــه يف‪1433/10/25‬ه ـ‬\n‫ولــم أجــد أحــد ومت الذهــاب مــرة ثانيــة يف‪1433/10/28‬ه ـ ولــم أجــد‬\n‫أحــد وذهبــت املــرة الثالثــة يف‪1433/11/01‬ه ـ فوجــدت ابنــه ‪ ...‬ومت‬\n‫تســليمه صــورة الصــك وجتــدون برفقــه منــوذج االســتالم)ا‪.‬هـ وبرفقــه‬\n‫إقــرار ابــن املدعــى عليــه ‪ ...‬املتضمــن أقــر أنــا ‪ ...‬بأننــي اســتلمت صــورة‬\n‫مــن صــك احلكــم رقــم ‪ 33430422‬وتاريــخ ‪1433/10/18‬ه ـ الصــادر‬\n‫مــن محكمــة ينبــع يف القضيــة املقامــة مــن املدعــي ‪ ...‬وأقــر بأنــي غيــر‬\n\n\n                                                                                      ‫‪248‬‬\n\f      ‫مقتنــع باحلكــم وســوف أتقــدم بالئحــة اعتراضيــة خــال ثالثــن يوم ـ ًا‬\n      ‫مــن اســتالمي للصــورة ومذيلــة الورقــة باســم املقــر مبــا فيــه ‪ ...‬وتوقيعــه‬\n      ‫ـاء علــى الفقــرة اخلامســة‬\n                                 ‫وتاريــخ االســتالم ‪1433/11/01‬ه ـ ا‪.‬ه ـ لــذا وبنـ ً‬\n      ‫مــن املــادة السادســة والســبعني بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n      ‫والئحتــه التنفيذيــة ونصهــا (إذا تعــذر تســليم نســخة صــك احلكــم‬\n      ‫الغيابــي إلــى احملكــوم عليــه أو وكيلــه رفــع احلكــم إلــى محكمــة‬\n      ‫التمييــز بــدون الئحــة اعتراضيــة ‪ ،‬وال مينــع ذلــك مــن التمــاس إعــادة‬\n      ‫النظــر وفــق أحكامــه املقــررة يف هــذا النظــام) ا‪.‬ه ـ لــذا فقــد قــررت‬\n      ‫رفــع كامــل املعاملــة حملكمــة االســتئناف مبكــة املكرمــة لدراســة‬\n      ‫احلكــم وتدقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم حــرر يف ‪1433/12/19‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ‬\n      ‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n      ‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪321185775‬‬\n      ‫وتاريــخ ‪1433/12/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة بينبــع املســجل برقــم ‪ ...‬وتاريــخ‬\n      ‫‪1433/10/18‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد ‪ ، ...‬وبدراســة الصــك وصــورة‬\n      ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل املوفــق‪ .‬وصل ــى اهلل عل ــى‬\n                                           ‫نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪249‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":244,"source_page_end":249,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e88adaabd7f1c042e49d85f0400f1682b2358fbb23162fdaae423e0857bfc6c1","normalized_text_hash":"df8fdfcb7ff7d5e2c964c26c9a661b7f8aa0924fe9f1900125b35788d5287e66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p244-33430422"},{"id":"94fd622a-901a-545c-b3fa-a9101bb99a8b","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم -مطالبة الكفيل مكفوله مببلغ سدده عنه -عدم حضور املدعى عليها رغم التبليغ -تقدمي املدعي البينة على صحة دعواه -النكول لعدم احلضور -إلزام املدعى عليها بسداد املبلغ وتبليغها بذلك .","document_number":"33442059","case_number":"46835","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/29","year":"1434","subject":"كفالة غرم -مطالبة الكفيل مكفوله مببلغ سدده عنه -عدم حضور املدعى عليها رغم التبليغ -تقدمي املدعي البينة على صحة دعواه -النكول لعدم احلضور -إلزام املدعى عليها بسداد املبلغ وتبليغها بذلك .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33442059 :‬تاريخه‪1433/10/29 :‬هـ‬\n                       ‫رقم الدعوى‪46835 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3411836‬تاريخه‪1434/1/13 :‬هـ‬\n\n\n ‫كفالــة غــرم ‪ -‬مطالبــة الكفيــل مكفولــه مببلــغ ســدده عنــه ‪ -‬عــدم‬\n ‫حضــور املدعــى عليهــا رغــم التبليــغ ‪ -‬تقــدمي املدعــي البينــة علــى صحــة‬\n ‫دعــواه ‪ -‬النكــول لعــدم احلضــور ‪ -‬إلــزام املدعــى عليهــا بســداد املبلــغ‬\n                                                             ‫وتبليغهــا بذلــك ‪.‬‬\n\n\n\n\n                                       ‫املادة ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليهــا الغائبــة عــن مجلــس احلكــم بأنهــا‬\n ‫اشــترت مــن أحــد األشــخاص مائتــي طاقــة قمــاش بخمســة وثالثــن‬\n ‫ألــف ريــال ولــم تســدد شــيئ ًا مــن القيمــة ثــم صــدر علــى املدعــي حكــم‬\n ‫بدفــع املبلــغ الســابق بحكــم كفالــة املدعــي للمدعــى عليهــا كفالــة‬\n ‫غــرم وقــد ســدد املدعــي للبائــع اثنــن وثالثــن ألف ـ ًا وخمســمائة ريــال‬\n ‫ويطلــب احلكــم عليهــا بســداد مــا دفعــه هكــذا ادعــى ‪ ،‬لــم حتضــر‬\n ‫املدعــى عليهــا مــع تبلــغ أحــد الســاكنني معهــا يف اجللســة األولــى وتبلــغ‬\n ‫ابنهــا باجللســة الثانيــة فجــرى ســماع الدعــوى غيابيــا بنــاء علــى املــادة ‪55‬‬\n ‫مــن نظــام املرافعــات الشــرعية ‪ ،‬بينــة املدعــي أصــل احلكــم الصــادر‬\n ‫بإلزامــه بدفــع املبلــغ بحكــم كفالتــه للمدعــى عليهــا ومهمــش عليــه‬\n\n                                                                                        ‫‪250‬‬\n\f      ‫بإقــرار املدعــي البائــع باســتالم املبلــغ املدعــى بــه وكذلــك عقــد البيــع‬\n      ‫ومذيــل بكفالــة املدعــي للمدعــى عليهــا وســند قبــض صــادر مــن البائــع‬\n      ‫باســتالمه مــن املدعــي مبلــغ وقــدره اثنــان وثالثــون ألف ـ ًا وخمســمائة‬\n      ‫ريــال ‪ ،‬ملــا تضمنــه صــك احلكــم وعقــد البيــع الســابق وإقــرار البائــع‬\n      ‫بســداد املدعــي للمبلــغ املدعــى بــه ونظــر ًا لعــدم حضــور املدعــى عليهــا‬\n      ‫رغــم تبلغهــا وهــذا نكــول منهــا عــن احلضــور وتــرك حلقهــا يف الدفــع ورد‬\n      ‫الدعــوى ‪ ،‬ملــا تقــدم صــدر احلكــم علــى املدعــى عليهــا غيابي ـ ًا بدفــع‬\n      ‫املبلــغ املدعــى بــه وقــدره اثنــان وثالثــون ألفـ ًا وخمســمائة ريــال وإبالغهــا‬\n      ‫بنســخة احلكــم لتقــدمي اعترضهــا باملــدة املقــررة نظامـ ًا ‪ ،‬صــدق احلكــم‬\n               ‫مــن الدائــرة احلقوقيــة الثالثــة مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 46835‬وتاريــخ ‪1429/11/14‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 29148930‬وتاريــخ ‪1429/11/14‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1431/03/23‬ه ـ افتتحــت اجللســة لســماع الدعــوى‬\n      ‫املقدمــة مــن ‪...‬ضــد ‪...‬حيــث مت حتديــد موعــد جلســة يف يــوم الثالثــاء‬\n      ‫املوافــق ‪1430/1/9‬ه ـ الســاعة الثامنــة وحضــر املدعــي ولــم حتضــر‬\n      ‫املدعــى عليهــا وقــد تبلــغ الســاكن معهــا ‪...‬مبوعــد اجللســة حســب إفــادة‬\n      ‫احملضــر ‪ ...‬علــى ورقــة التبليــغ املؤرخــة يف ‪1429/11/14‬ه ـ كمــا مت‬\n      ‫حتديــد موعــد جلســة يف يــوم األحــد املوافــق ‪1430/3/18‬ه ـ الســاعة‬\n      ‫التاســعة صباح ـ ًا ولــم حتضــر املدعــى عليهــا وقــد تبلــغ أبنهــا ‪ ...‬مبوعــد‬\n‫‪251‬‬\n\f‫اجللســة حســب خطــاب مديــر مركــز شــرطة العزيزيــة املقيــد برقــم‬\n‫‪ 30/42857‬يف ‪1430/3/18‬ه ـ كمــا مت حتديــد موعــد جلســة يف يــوم‬\n‫االثنــن املوافــق ‪1430/11/21‬ه ـ الســاعة احلاديــة عشــر ومت مخاطبــة‬\n‫إمــارة منطقــة الريــاض برقــم ‪ 30/109161‬يف ‪1430/7/18‬ه ـ للتعميــم‬\n‫عــن املدعــى عليهــا وإبالغهــا مبوعــد اجللســة فوردنــا خطــاب مديــر‬\n‫شــرطة الديــرة رقــم ‪ 8553‬يف ‪1430/12/1‬ه ـ بأنــه مت التعميــم عــن‬\n‫املدعــى عليهــا وال يــزال البحــث جاري ـ ًا عنهــا كونهــا متهربــة ومختفيــة‬\n‫عــن األنظــار ويف هــذا اليــوم الثالثــاء املوافــق ‪1431/3/23‬ه ـ مت حتديــد‬\n‫موعــد جلســة الســاعة التاســعة لســماع الدعــوى وقــد حضــر املدعــي‬\n‫أصالــة مبوجــب الســجل املدنــي رقــم ‪...‬ولــم حتضــر املدعــى عليهــا وال‬\n‫وكيــل عنهــا وبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية فقــد‬\n‫قــررت ســماع الدعــوى غيابيـ ًا وبســؤال املدعــي عــن دعــواه قــال اشــترت‬\n‫املدعــى عليهــا مــن ‪...‬مائتــي طاقــة دوبلــن بخمســة وثالثــن ألــف ريــال‬\n‫بتاريــخ ‪1420/8/30‬ه ـ ولــم تســدد شــيئ ًا مــن القيمــة ثــم صــدر علــي‬\n‫حكــم منكــم برقــم ‪ 31/279‬يف ‪1427/12/27‬ه ـ بدفــع املبلــغ الســابق‬\n‫بحكــم كفالتــي لهــا كفالــة غــرم وقــد ســددت للبائــع أثنــن وثالثــن‬\n‫ألــف وخمســمائة ريــال ولــم تدفــع لــي شــيئ ًا أطلــب احلكــم عليهــا بســداد‬\n‫مــا دفعتــه هــذه دعــواي وبســؤال املدعــي عــن البينــة أبــرز أصــل احلكــم‬\n‫الســابق الصــادر منــا برقــم ‪ 31/279‬يف ‪1427/12/27‬ه ـ ويتضمــن‬\n‫دعــوى ‪...‬ضــد احلاضــر مببلــغ خمســة وثالثــن ألــف ريــال قيمــة مائتــي‬\n‫طاقــة دوبلــن اشــترتها منــه ‪...‬بتاريــخ ‪1420/8/30‬ه ـ ولــم تســدد شــيئ ًا‬\n‫وكفلهــا احلاضــر كفالــة غــرم وقــد صــدر احلكــم عليــه بدفــع املبلــغ‬\n‫ا وقــد همــش عليــه بإقــرار املدعــي باســتالم كامــل املبلــغ ولــم‬   ‫كام ـ ً‬\n\n\n                                                                                    ‫‪252‬‬\n\f      ‫يســبق لــه يف ذمــة احلاضــر أي مبلــغ كمــا أبــرز أصــل عقــد البيــع املــدون‬\n      ‫يف صــك احلكــم ويتضمــن إقــرار املدعــى عليهــا ‪ ...‬بشــراء واســتالم‬\n      ‫مائتــي طاقــة دوبلــن يف ‪1420/9/1‬ه ـ وقيمتهــا خمســة وثالثــون ألــف‬\n      ‫ريــال مــن ‪...‬وقــد كفلهــا احلاضــر ‪ ...‬كفالــة غــرم وأداء وعليــه توقيــع‬\n      ‫املدعــى عليهــا وبصمتهــا كمــا أبــرز ســند قبــض صــادر مــن البائــع ‪...‬‬\n      ‫بتاريــخ ‪1428/4/6‬ه ـ يتضمــن اســتالمه مــن احلاضــر اثنــان وثالثــون‬\n      ‫ألــف وخمســمائة ريــال مبوجــب كفالــة غــرم ‪...‬مبوجــب ســند قبــض رقــم‬\n      ‫‪ 3572‬يف ‪1428/4/6‬ه ـ وأصبــح حســابه خالــص فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى ومــا تضمنــه صــك احلكــم وعقــد البيــع الســابق وإقــرار‬\n      ‫البائــع بســداد املدعــي للمبلــغ املدعــى بــه ونظــر ًا لعــدم حضــور املدعــى‬\n      ‫عليهــا رغــم تبلغهــا وهــذا نكــول منهــا عــن احلضــور وتــرك حلقهــا يف‬\n      ‫الدفــع ورد الدعــوى لــذا فقــد حكمــت علــى املدعــى عليهــا غيابيـ ًا بدفــع‬\n      ‫املبلــغ املدعــى بــه وقــدره اثنــان وثالثــون ألف ـ ًا وخمســمائة ريــال وقــررت‬\n      ‫إبالغهــا بنســخة احلكــم لتقــدمي اعتراضهــا عليــه خــال ثالثــن يومـ ًا مــن‬\n      ‫تاريــخ تبلغهــا وإال ســقط حقهــا يف االعتــراض عليــه ويكتســب احلكــم‬\n      ‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1431/03/23‬ه ـ‬\n      ‫ثــم إنــه يف يــوم االثنــن املوافــق ‪1432/11/12‬ه ـ افتتحــت اجللســة وحضر‬\n      ‫املدعــي أصالــة كمــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وقــرر احلاضــر بقولــه بــأن املدعــى عليهــا زوجتــي وأننــي مســتعد‬\n      ‫بالســداد عنهــا وقــد أحضــرت املبلــغ احملكــوم بــه نقــدا ثــم قــام بتســليمه‬\n      ‫للمدعــي وقــرر املدعــي بأنــه لــم يعــد لــه أي مطالبــة جتــاه املدعــى عليهــا‬\n      ‫حيــث اســتلم املبلــغ الــذي يطالبــه بهــا وبــذا تكــون الدعــوى منتهيــة‬\n\n\n‫‪253‬‬\n\f‫وكان ذلــك بشــهادة كاتبــي الضبــط ‪...‬و‪...‬وصلــى اهلل وســلم علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه أجمعــن‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد باخلطــاب‬\n‫رقــم ‪ 31183877‬وتاريــخ ‪1433/12/29‬ه ـ املرفــق بهــا الصــك رقــم‬\n‫‪ 33442059‬وتاريــخ ‪1433/10/29‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪... /‬بشــأن الدعــوى املقامــة مــن ‪ ... /‬ضــد ‪.... /‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫تقــرر الدائــرة باألكثريــة املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪254‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":250,"source_page_end":254,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e794b4ef0f92b36ac5059732790a18dee6c3cb183eec00338bf00e0a6bed2a48","normalized_text_hash":"e4cc893f178fd796c5ae87137b4e330065f47273d9136db277d98cae7ee9180e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p250-33442059"},{"id":"b82ce4f2-6ae4-5aed-9a4d-0698860ab903","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع سيارة بأقساط -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -عدم احلضور رغم التبليغ - شهادة الشهود -حلف املدعي اليمن -إلزام املدعى عليه (الكفيل) بسداد املبلغ احلال -للكفيل الرجوع على مكفوله فيما سدده .","document_number":"34279891","case_number":"34104369","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"كفالة غرم وأداء -بيع سيارة بأقساط -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -عدم احلضور رغم التبليغ - شهادة الشهود -حلف املدعي اليمن -إلزام املدعى عليه (الكفيل) بسداد املبلغ احلال -للكفيل الرجوع على مكفوله فيما سدده .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34279891 :‬تاريخه‪1434/7/25 :‬هـ‬\n                        ‫رقم الدعوى‪34104369 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34390591‬تاريخه‪1434/12/29 :‬هـ‬\n\n\n      ‫كفالــة غــرم وأداء ‪ -‬بيــع ســيارة بأقســاط‪ -‬مطالبــة الكفيــل بتســليم‬\n      ‫باقــي ثمــن ســيارة اشــتراها مكفولــه ‪ -‬عــدم احلضــور رغــم التبليــغ ‪-‬‬\n      ‫شــهادة الشــهود ‪ -‬حلــف املدعــي اليمــن ‪ -‬إلــزام املدعــى عليــه (الكفيــل)‬\n        ‫بســداد املبلــغ احلــال ‪ -‬للكفيــل الرجــوع علــى مكفولــه فيمــا ســدده ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) رواه ابــن ماجــة‬\n                                                               ‫وحســنه النــووي ‪.‬‬\n               ‫‪ .2‬املادة ‪ 55‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n           ‫‪ .3‬املادة ‪ 3/147‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه الكفيــل الغــارم الغائــب عــن مجلــس‬\n      ‫احلكــم يطالبــه بســداد مبلــغ وقــدره ســتة وتســعون ألفـ ًا وأربعمائــة ريال‪،‬‬\n      ‫حيــث بــاع املدعــي ســيارتني علــى مكفــول املدعــى عليــه مببلــغ إجمالــي‬\n      ‫قــدره مائــة وســبعة وعشــرون ألــف ريــال مقســطة علــى أقســاط شــهرية‬\n      ‫ســدد منهــا مبلغ ـ ًا وقــدره ثالثــون ألف ـ ًا وســتمائة ريــال والباقــي مبلــغ‬\n      ‫وقــدره ســتة وتســعون ألفـ ًا وأربعمائــة ريــال وقــد حــل منــه تســعة وثالثــن‬\n      ‫ألــف وأربعمائــة ريــال يطالــب بإلزامــه بتســليم املبلــغ احلــال ودفــع املؤجــل‬\n\n‫‪255‬‬\n\f‫يف حينــه ‪ ،‬جــرى ســماع الدعــوى غيابي ـ ًا لتبلــغ املدعــى عليــه لشــخصه‬\n‫‪ ،‬بينــة املدعــي عقــد املبايعــة وشــهادة الشــاهدين املعدلــن شــرع ًا طبــق‬\n‫دعــواه إال أنهمــا ال يعلمــان بالواصــل واملتبقــي مــن املبلــغ ‪ ،‬حلــف املدعــي‬\n‫اليمــن طبــق دعــواه ‪ ،‬بنــاء علــى شــهادة الشــاهدين املعدلــن شــرع ًا‬\n‫واالتفاقيــة واليمــن مــن املدعــي وبنــاء علــى املــادة اخلامســة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية والالئحــة التنفيذيــة ونظــر ًا ملماطلــة‬\n‫املدعــى عليــه باحلضــور رغــم تبلغــه شــخصي ًا وبعــد االطــاع علــى املــادة‬\n‫‪ 3/147‬مــن نظــام املرافعــات الشــرعية وحيــث أن املدعــي متضــرر مــن‬\n‫التأخيــر يف نظــر القضيــة وألن الضــرر مرفــوع يف الشــريعة لقــول النبــي‬\n‫صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) رواه ابــن ماجــة وحســنه‬\n‫النــووي ‪ ،‬ثبــت أن بذمــة املدعــى عليــه للمدعــي باألصالــة مبلغـ ًا مقــداره‬\n‫ســتة وتســعون ألف ـ ًا وأربعمائــة ريــال ‪ ،‬ملــا تقــدم صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه أن يســلم املبلــغ احلــال ويدفــع املؤجــل يف حينــه ولــه الرجــوع‬\n‫علــى مكفولــه فيمــا يســدد عنــه ‪ ،‬قنــع املدعــي باحلكــم ورفعــت اجللســة‬\n‫لتبليــغ املدعــى عليــه باحلكــم ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                ‫الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنــورة‪ /‬املســاعد برقــم ‪ 34104369‬وتاريــخ‬\n‫‪ 1434/03/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34544155‬وتاريــخ‬\n‫‪ 1434/03/02‬ه ـ ففــي يــوم الثالثــاء‪ 1434/07/11‬ه ـ حضــر املدعــي‬\n\n                                                                                       ‫‪256‬‬\n\f      ‫‪.......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬ولــم يحضــر املدعــى عليــه ‪.......‬‬\n      ‫رغــم تبلغــه مبوعــد اجللســة هــذا اليــوم بنفســه وتوقيعــه حســب إفــادة‬\n      ‫رئيــس قســم احملضريــن باحملكمــة ‪ .‬ويف يــوم االثنــن ‪1434/7/24‬ه ـ‬\n      ‫حضــر املدعــي ‪.......‬ولــم يحضــر املدعــى عليــه ‪.......‬صاحــب الســجل‬\n      ‫مدنــي رقــم ‪.......‬رغــم تبلغــه باملوعديــن الســابقني لشــخصه مــن قســم‬\n      ‫احملضريــن جلســة يف ‪1434/5/7‬ه ـ وجلســة يف ‪1434/7/11‬ه ـ حســب‬\n      ‫ا ‪ :‬إنــه بتاريــخ‬‫إفــادة رئيــس قســم احملضريــن وفيهــا قــرر املدعــي قائ ـ ً‬\n      ‫‪1432/3/21‬ه ـ بعــت ‪..............‬ســيارتني نيســان غمــارة موديــل ‪2008‬م‬\n      ‫رقــم هيــكل األولــى ‪ .......‬ورقــم هيــكل الثانيــة ‪.......‬أوراق جمــرك‬\n      ‫مببلــغ إجمالــي مقــداره مائــة وســبعة وعشــرون ألــف ريــال ‪ 127000‬علــى‬\n      ‫أقســاط شــهرية كل شــهر ألفــن وخمســمائة ‪ 2500‬ريــال اعتبــار ًا مــن‬\n      ‫‪1432/4/30‬ه ـ حتــى ينتهــي املبلــغ وســدد منهــا ثالثــن ألف ـ ًا وســتمائة‬\n      ‫ريــال ‪ 30600‬وبقــي بذمتــه ســتة وتســعني الف ـ ًا واربعمائــة ريــال وحــل‬\n      ‫منهــا تســعة وثالثــن الفـ ًا واربعمائــة ريــال ومبــا أن املدعــى عليــه كفيــل‬\n      ‫غــارم وأطلــب إلزامــه بتســليم املبلــغ احلــال ودفــع املؤجــل يف حينــه حســب‬\n      ‫األقســاط هــذه دعــواي ثــم طلبــت البينــة مــن املدعــي فأبــرز عقــد املبايعــة‬\n      ‫وهــذا نصــه (( التاريــخ ‪1432/3/21‬ه ـ اقــر أنــا املوقــع اســمي أدنــاه ‪.......‬‬\n      ‫بأننــي قــد اشــتريت عــدد ســيارتني نيســان غمــارة موديــل ‪2008‬م بنمــرة‬\n      ‫واســتمارة حــرة رقــم االســتمارة بطاقــه جمركيــه مــن املكــرم ‪.........‬‬\n      ‫مبلــغ وقــدره مائــة وســبعة وعشــرون الــف ريــال ‪ 127000‬وقــد دفعــت‬\n      ‫حــال توقيعــي علــى عقــد املبايعــة مبلــغ وقــدره بــدون والباقــي وقــدره‬\n      ‫مائــة وســبعة وعشــرون الــف ريــال معــدل كل شــهر مبلــغ وقــدره ألفــن‬\n      ‫وخمســمائة ‪ 2500‬ريــال ابتــداء مــن نهايــة شــهر ‪1432/4/30‬ه ـ رقــم‬\n\n\n‫‪257‬‬\n\f‫احلاســب اآللــي ‪ 1047336290‬تاريخهــا ‪1408/12/22‬ه ـ مصدرهــا‬\n‫املدينــة وقــد اســتلمت الســيارتني وحزتهمــا وأذنــت ملــن يشــهد شــاهد‬\n‫‪ ........‬توقيعــه شــاهد ‪.......‬توقيعــه املشــتري ‪.......‬توقيعــه أقــرر أنــا ‪.......‬‬\n‫ا أنــي كفلــت املدعــو ‪.......‬كفالــة غــرم وأداء ويف حــال تأخــره عــن‬         ‫قائـ ً‬\n‫الدفــع أو وفاتــه ســوف أدفــع املبلــغ عنــه بــدون تأخيــر أو مماطلــة وعليــه‬\n‫أوقــع رقــم احلاســب اآللــي ‪ 1031426420‬تاريخهــا ‪1407/12/2‬ه ـ‬\n‫مصدرهــا املدينــة املقــر ‪.......‬توقيعــه ا‪.‬ه ـ ثــم طلبــت مــن املدعــي زيــادة‬\n‫ال مــن ‪....... -1‬مــن مواليــد املدينــة‬   ‫بينــه فأحضــر للشــهادة وأدائهــا ك ً‬\n‫عــام ‪1372‬ه ـ مبوجــب الســجل املدنــي رقــم (‪....... -2 ).......‬مــن مواليــد‬\n‫املدينــة عــام ‪1377‬ه ـ مبوجــب الســجل املدنــي رقــم (‪ ).......‬وشــهد كل‬\n‫ا ‪ :‬أشــهد أنــه بتاريــخ ‪1432/3/21‬ه ـ بــاع‬          ‫واحــد منهمــا منفــرد ًا قائ ـ ً‬\n‫املدعــي ‪.......‬ســيارتني نيســان غمــارة موديــل ‪2008‬م علــى ‪.......‬مببلــغ‬\n‫مائــة وســبعة وعشــرين الــف ريــال علــى أقســاط شــهرية كل قســط‬\n‫ـداء مــن ‪1432/4/30‬ه ـ حتــى ينتهــي‬         ‫ألفــن وخمســمائة ‪ 2500‬ريــال ابتـ ً‬\n‫املبلــغ وأشــهد أن املدعــى عليــه ‪.......‬كفلــه كفالــة غــرم وأداء يف كامــل‬\n‫املبلــغ وال نعلــم كــم الواصــل أو الباقــي هــذه شــهادتي ثــم جــرى تزكيــة‬\n‫الشــاهدين مــن قبــل كل مــن ‪....... -1‬ي ســجل مدنــي رقــم (‪-2 ).......‬‬\n‫‪.......‬ســجل مدنــي رقــم (‪ ).......‬ثــم طلبــت ميــن االســتظهار مــن املدعــي‬\n‫ا ‪ :‬أقســم بــاهلل العظيــم أنــه‬     ‫فاســتعد بهــا وبعــد إذنــي لــه حلــف قائ ـ ً‬\n‫بتاريــخ ‪1432/3/21‬ه ـ بعــت ســيارتني نيســان غمــارة انتــاج ‪2008‬م‬\n‫‪.......‬مببلــغ مائــة وســبعة وعشــرين ألــف ريــال علــى أقســاط شــهريه قــدر‬\n‫كل قســط ألفــن وخمســمائة ريــال اعتبــار ًا مــن ‪1432/4/30‬ه ـ حتــى‬\n‫ينتهــي املبلــغ و واهلل العظيــم أنــه لــم يســدد منهــا ســوى ثالثــن الف ـ ًا‬\n\n\n                                                                                           ‫‪258‬‬\n\f      ‫وســتمائة ريــال والتــزال بذمــة املشــتري واملدعــى عليــه ســتة وتســعني الفـ ًا‬\n      ‫واربعمائــة ريــال وأن احلــال منهــا تســعة وثالثــن الفـ ًا وأربعمائــة ريــال حتى‬\n      ‫تاريــخ ‪1434/7/30‬ه ـ وأن املدعــى عليــه ‪.......‬كفلــه كفالــة غــرم‬\n      ‫واداء يف كامــل املبلــغ واهلل العظيــم هــذه ميينــي ثــم إنــه وبعــد التأمــل يف‬\n      ‫القضيــة وبعــد ســماع دعــوى املدعــي وشــهادة الشــاهدين املعدلــن شــرع ًا‬\n      ‫وبعــد االطــاع علــى اتفاقيــة بيــع الســيارة بالتقســيط وبعــد ســماع ميــن‬\n      ‫االســتظهار مــن املدعــي وبعــد االطــاع علــى املــادة اخلامســة واخلمســن‬\n      ‫مــن نظــام املرافعــات الشــرعية والالئحــة التنفيذيــة ونظــر ًا ملماطلــة‬\n      ‫املدعــى عليــه باحلضــور رغــم تبلغــه شــخصي ًا وبتوقيعــه باحلضــور مرتــن‬\n      ‫وبعــد االطــاع علــى املــادة ‪ 3/147‬مــن نظــام املرافعــات الشــرعية وحيــث‬\n      ‫أن املدعــي متضــرر مــن التأخيــر يف نظــر القضيــة وألن الضــرر مرفوع يف‬\n      ‫الشــريعة لقــول النبــي صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) رواه‬\n      ‫ابــن ماجــة وحســنه النــووي لذلــك كلــه فقــد ثبــت لــدي أن بذمــة املدعــى‬\n      ‫عليــه ‪ ......‬للمدعــي باألصالــة ‪.......‬مبلغ ـ ًا مقــداره ســتة وتســعني ألف ـ ًا‬\n      ‫وأربعمائــة ريــال ويلــزم املدعــى عليــه أن يســلم املبلــغ احلــال مــن األقســاط‬\n      ‫حــا ًال ويدفــع املؤجــل يف حينــه ولــه الرجــوع علــى مكفولــه فيمــا يســدد‬\n      ‫عنــه وهــذا مــا ظهــر لــي وبــه حكمــت وقنــع املدعــي باحلكــم وأمــرت‬\n      ‫بتبليــغ املدعــى عليــه بنســخة مــن احلكــم لتقــدمي الالئحــة االعتراضيــة إن‬\n      ‫رغــب يف مهلــة ثالثــن يومـ ًا مــن حــن تبليغــه ثــم ترفــع القضيــة حملكمــة‬\n      ‫االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/25‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n\n\n‫‪259‬‬\n\f‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪.......‬القاضــي باحملكمــة العامــة باملدينــة املنــورة واملســجل بعــدد‬\n‫‪ 34279891‬وتاريــخ ‪1434/7/25‬ه ـ املتضمــن دعــوى ‪.......‬ضــد ‪.......‬‬\n‫واحملكــوم فيــه مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطه تقررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                          ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":255,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5e35dd5693cf404ce65faea05ee4364b9bad1699a8b766f4f0572fd345dc310a","normalized_text_hash":"05e404f8b2911bea1a4ab77c5ab9771db80e8aab259f195f92a2bebf22ded9de","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p255-34279891"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

